 return {'all_rank_receipt':a['receipt'],'slowest_rank_per_sample':{k:summary([max(rank[s][phase][k] for rank in ms) for s in range(3)]) for k in metrics},'peak_allocated_bytes_max_across_ranks_and_samples':max(m[phase]['peak_allocated_bytes'] for r in ms for m in r),'peak_reserved_bytes_max_across_ranks_and_samples':max(m[phase]['peak_reserved_bytes'] for r in ms for m in r),'peak_allocated_bytes_by_rank':[max(m[phase]['peak_allocated_bytes'] for m in r) for r in ms],'peak_reserved_bytes_by_rank':[max(m[phase]['peak_reserved_bytes'] for m in r) for r in ms],'starting_allocated_bytes_min_max':[min(m['starting_bytes']['allocated'] for r in ms for m in r),max(m['starting_bytes']['allocated'] for r in ms for m in r)]}
